const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',box:'m12 3 9 5-9 5-9-5 9-5z M3 8v9l9 5 9-5V8 M12 13v9',calendar:'M5 5h14v16H5z M8 2v6 M16 2v6 M5 10h14',leaf:'M20 3C7 1 2 8 6 15s14 3 14-12z M5 21 17 7',chart:'M4 20h17 M7 16V9 M12 16V4 M17 16v-5',arrow:'M4 12h16 m-6-6 6 6-6 6',plus:'M12 4v16 M4 12h16',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16z m6-2 6 6',bell:'M18 8a6 6 0 0 0-12 0c0 9-3 9-3 9h18s-3 0-3-9 M10 21h4',chevron:'m9 5 7 7-7 7',check:'m4 12 5 5L20 6',close:'m5 5 14 14 M19 5 5 19',logout:'M9 4H4v16h5 M10 12h11 m-5-5 5 5-5 5',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M12 6v6l4 2',tool:'M14 5a6 6 0 0 0-7 7L2 17l5 5 5-5a6 6 0 0 0 7-7l-4 4-5-5 4-4z',camera:'M3 6h5l2-3h5l2 3h4v14H3z M12 17a4 4 0 1 0 0-8 4 4 0 0 0 0 8z',chip:'M5 5h14v14H5z M9 9h6v6H9z M8 1v4 M16 1v4 M8 19v4 M16 19v4 M1 8h4 M1 16h4 M19 8h4 M19 16h4',scope:'M9 3h6v10H9z M7 5h2 M9 11c-7 2-5 10 1 10h10 M13 13v4 M6 17h12 M17 6c5 1 6 7 3 11',meter:'M6 2h12v20H6z M9 5h6v5H9z M12 13v4 M10 15h4',audio:'M8 3h8v11H8z M5 10v4a7 7 0 0 0 14 0v-4 M12 21v-1 M8 22h8',printer:'M5 3h14v18H5z M8 7h8 M8 17h8 M12 7v6 m-3 0h6',laptop:'M5 3h14v13H5z M2 20h20l-3-4H5z',tripod:'M9 3h6v5H9z M12 8v4 m0 0-8 10 M12 12l8 10 M12 12v10',sensor:'M5 4h14v16H5z M9 8h6 M9 12h6 M9 16h3 M2 8h3 M19 8h3',projector:'M3 7h18v11H3z M6 10h4 M16 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6z M6 18v3 M18 18v3',ruler:'m4 3 17 17-4 4L0 7z M5 8l2-2 M9 12l2-2 M13 16l2-2',vr:'M3 8h18v11h-5l-4-3-4 3H3z M8 8V5h8v3 M6 11h3 M15 11h3',user:'M12 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10z M3 22c0-10 18-10 18 0',menu:'M3 6h18 M3 12h18 M3 18h18',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20z M12 10v7 M12 6v1'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.box}"/></svg>`;
let state={user:null,csrf:'',today:'',demo:false,assets:[],loans:[],stats:{},maintenance:[],notifications:[],page:'dashboard',category:'All equipment',query:'',from:'',to:'',availability:false,weekStart:'',plannerData:null,plannerCategory:'All categories'};
const dayAdd=(day,n)=>new Date(Date.parse(day+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
const date=day=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short'}).format(new Date(day.slice(0,10)+'T12:00:00Z'));
const statusLabel={pending:'Awaiting approval',approved:'Ready for pickup',checked_out:'In use',returned:'Returned',rejected:'Declined',cancelled:'Cancelled'};
function toast(message,bad=false){const el=$('#toast');el.textContent=message;el.className=bad?'show error':'show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500);}
async function api(path,options={}){const response=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...(options.method?{'X-CSRF-Token':state.csrf}:{}),...options.headers},body:options.body?JSON.stringify(options.body):undefined});const data=await response.json();if(!response.ok){if(response.status===401&&state.user){state.user=null;render();}throw new Error(data.error||'Please try again.');}return data;}
async function load(){Object.assign(state,await api('/bootstrap'));state.plannerData=null;state.from ||= state.today;state.to ||= dayAdd(state.today,1);if(state.from<state.today){state.from=state.today;state.to=dayAdd(state.today,1);}if(state.from!==state.today||state.to!==dayAdd(state.today,1))state.assets=(await api(`/assets?from=${state.from}&to=${state.to}`)).assets;if(state.user.role==='student'&&['maintenance','activity'].includes(state.page))state.page='dashboard';render();}
const badge=l=>`<span class="badge ${esc(l.overdue?'overdue':l.status)}">${esc(l.overdue?'Return overdue':statusLabel[l.status]||l.status)}</span>`;
function topTitle(){return {dashboard:['Your learning commons','A good day to make something.'],catalog:['Equipment library','The right tools, ready to share.'],planner:['Availability planner','Find the right moment to make.'],loans:[state.user.role==='staff'?'Borrowing desk':'My borrowing','Every handover, in one place.'],maintenance:['Care & repair','Keep good tools in circulation.'],insights:['Resource insights','See how your workspace is used.'],activity:['Activity journal','A record you can follow.']}[state.page]||['PinjamLab','Make room for your next idea.'];}
const logo=()=>`<a class="brand" href="#dashboard"><img src="/assets/mark.svg" alt="" width="42" height="42"><span>Pinjam<span class="brand-light">Lab</span><small>THE SHARED LEARNING COMMONS</small></span></a>`;
function render(){if(!state.user){renderLogin();return;}const [title,subtitle]=topTitle(),role=state.user.role;$('#app').innerHTML=`<div class="workspace"><aside class="sidebar" id="workspace-nav"><button class="sidebar-close icon-button" data-action="menu" aria-label="Close navigation">${icon('close')}</button>${logo()}<div class="workspace-label"><span class="live-dot"></span>${role==='staff'?'LAB TEAM WORKSPACE':'LEARNER WORKSPACE'}</div><nav aria-label="Main navigation">${[['dashboard','grid','Overview'],['catalog','box','Equipment library'],['planner','calendar','Availability planner'],['loans','calendar',role==='staff'?'Borrowing desk':'My borrowing'],...(role==='staff'?[['maintenance','tool','Care & repair']]:[]),['insights','chart','Resource insights'],...(role==='staff'?[['activity','clock','Activity journal']]:[])].map(([id,i,name])=>`<a href="#${id}" class="nav-link ${state.page===id?'active':''}" ${state.page===id?'aria-current="page"':''}>${icon(i)}<span>${name}</span>${id==='loans'&&role==='staff'&&state.stats.pending?`<b>${state.stats.pending}</b>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sdg-note">${icon('leaf')}<p>More learning.<br><strong>Less left unused.</strong></p><span>04 / 12</span></div><button class="account" data-action="account"><span class="avatar">${esc(state.user.name[0])}</span><span><strong>${esc(state.user.name)}</strong><small>${role==='staff'?'Lab coordinator':'Student member'}</small></span>${icon('logout')}</button></div></aside><button class="nav-scrim" data-action="menu" aria-label="Close navigation"></button><div class="main-shell"><header class="topbar"><button class="icon-button mobile-menu" aria-label="Open navigation" aria-controls="workspace-nav" aria-expanded="false" data-action="menu">${icon('menu')}</button><div><p>${esc(title)}</p><span>${esc(subtitle)}</span></div><div class="top-actions"><button class="quick-find" data-action="quick-find" aria-label="Find equipment, shortcut Control K">${icon('search')}<span>Find a tool</span><kbd>Ctrl K</kbd></button><button class="motion-toggle" data-action="motion" aria-pressed="false" aria-label="Reduce interface motion">${icon('leaf')}<span>Motion</span></button><span class="date-stamp">${date(state.today)} ${state.today.slice(0,4)}</span><button class="icon-button notification-toggle" aria-label="Notifications" data-action="notifications">${icon('bell')}${state.notifications.some(n=>!n.read_at)?'<i></i>':''}</button><span class="top-avatar">${esc(state.user.name[0])}</span></div></header><main id="main" tabindex="-1">${pageContent()}</main><footer class="app-footer"><span>PINJAMLAB <span class="footer-dot">•</span> KEBAS, UNIVERSITAS MIKROSKIL</span><span>${state.demo?'Sample workspace · illustrative records':'Learning resources, shared responsibly'} <span class="live-dot"></span></span></footer></div></div>`;bind();setupMotion();}
function renderLogin(){$('#app').innerHTML=`<div class="login-page"><header>${logo()}<span class="edition">FUNDEV INTERNATIONAL 2026</span></header><main class="login-main" id="main"><section class="login-story"><span class="eyebrow"><i></i> A LITTLE SHARING GOES A LONG WAY</span><h1>Big ideas.<br><em>Shared tools.</em></h1><p>Find the equipment you need. Make something worth sharing. Return it ready for the next good idea.</p><div class="login-art"><span class="login-orbit" aria-hidden="true"></span><span class="login-art-label">ONE TOOLBOX.<br>MANY POSSIBILITIES.</span><img src="/assets/equipment-loop.png" alt="Illustration of a shared camera, electronics kit and multimeter" width="620" height="390"><span class="art-caption">BORROW. CREATE. RETURN. REPEAT.</span></div><div class="login-process"><span><b>01</b> Discover</span><i>→</i><span><b>02</b> Create</span><i>→</i><span><b>03</b> Share again</span></div><div class="login-bottom"><span>Built for learning communities</span><span>SDG 04 <span class="footer-dot">/</span> SDG 12</span></div></section><section class="login-form-panel"><span class="paper-number">01 / THE COMMONS</span><h2>Your next idea<br>starts here.</h2><p class="muted">Sign in to your learning workspace.</p><form id="login-form"><label>Email address<input type="email" name="email" placeholder="you@university.edu" required autocomplete="username"></label><label>Password<input type="password" name="password" placeholder="Your password" required autocomplete="current-password"></label><p class="form-error" id="login-error" role="alert"></p><button class="button primary wide" type="submit">Sign in ${icon('arrow')}</button></form><button class="text-button register-toggle" data-action="register">New here? Create a learner account ${icon('chevron')}</button>${state.demo?`<div class="sample-divider"><span>EXPLORE THE SAMPLE WORKSPACE</span></div><div class="sample-buttons"><button class="button outline" data-demo="student">${icon('user')}As a learner</button><button class="button outline" data-demo="staff">${icon('tool')}As the lab team</button></div><p class="sample-disclosure">Illustrative equipment and borrowing records. Changes are saved in this workspace.</p>`:''}<div class="login-footnote">${icon('leaf')}Useful things deserve another chapter.</div></section></main><footer class="login-footer">PinjamLab · Circular Equipment Sharing for Inclusive Learning<span>KEBAS (Keluarga Bebas) · Indonesia</span></footer></div>`;
 document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{Object.assign(state,await api('/auth/demo',{method:'POST',body:{role:b.dataset.demo}}));await load();}catch(e){toast(e.message,true);b.disabled=false;}});
 $('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{Object.assign(state,await api('/auth/login',{method:'POST',body:Object.fromEntries(new FormData(e.target))}));await load();}catch(error){$('#login-error').textContent=error.message;b.disabled=false;}};$('[data-action="register"]').onclick=registerModal;setupMotion();
}
function hero(){const s=state.stats;return `<section class="hero"><div class="hero-copy"><span class="eyebrow"><i></i> YOUR NEXT IDEA, WITHIN REACH</span><h1>Make more.<br><em>Own less.</em><span class="hero-period">↗</span></h1><p>A camera. A circuit. A new possibility.<br>Great tools belong in great ideas.</p><div class="hero-ctas"><a class="button primary" href="#catalog">Explore the library ${icon('arrow')}</a><a class="hero-secondary" href="#planner">Plan your week ${icon('calendar')}</a></div><div class="hero-meta"><span class="mini-avatars"><b>A</b><b>M</b><b>R</b></span><span>One library. Many possibilities.</span></div></div><div class="hero-visual"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-spark spark-one" aria-hidden="true">✳</div><div class="hero-spark spark-two" aria-hidden="true">+</div><span class="orbit-label">DESIGNED TO KEEP GOOD THINGS GOING</span><img class="hero-equipment" src="/assets/equipment-loop.png" alt="Shared camera, electronics kit and multimeter illustration" width="600" height="390"><div class="floating-tag">${icon('check')} Ready for your next project</div><div class="hero-stock"><span class="live-dot"></span><strong>${s.available_units}</strong><span>units ready<br>today</span></div><span class="hero-serial">THE CIRCULAR LEARNING COLLECTION / 01</span></div></section>`;}
function statCards(){const s=state.stats;return `<section class="stats-grid" aria-label="Workspace overview">${[['box',s.available_units,'Units available today','Ready for your next idea','catalog'],['calendar',s.active,'Loans in use','Learning in progress','loans'],['leaf',s.completed,'Completed loans','Shared, returned, ready again','insights'],['tool',s.maintenance_units,'Units under care','Inspection before the next loan',state.user.role==='staff'?'maintenance':'insights']].map(([i,n,label,caption,target])=>`<a class="stat-card" href="#${target}"><div><span class="stat-icon">${icon(i)}</span><span>${i==='leaf'?'CIRCULAR USE':'THE COMMONS'} ${icon('arrow')}</span></div><strong data-count="${n??0}" aria-label="${n??0}">${n??0}</strong><h3>${label}</h3><p>${caption}</p></a>`).join('')}</section>`;}
function assetCard(a){return `<article class="equipment-card"><div class="equipment-art art-${a.id%4}"><span class="equipment-code">${esc(a.code)}</span><span class="equipment-floor"></span>${productArt(a.icon)}<span class="equipment-quantity">${a.total} shared units</span></div><div class="equipment-body"><div class="card-label"><span>${esc(a.category)}</span><span class="stock ${a.available?'in-stock':''}"><i></i>${a.available?`${a.available} available`:'Fully reserved'}</span></div><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><div class="equipment-footer"><span>${esc(a.location)}</span><button class="round-button" data-asset="${a.id}" aria-label="View ${esc(a.name)}">${icon('arrow')}</button></div></div></article>`;}
function loanRows(loans,compact=false){if(!loans.length)return `<div class="empty-state">${icon('calendar')}<h3>A little room for your next idea</h3><p>Your borrowing activity will appear here.</p><a href="#catalog" class="button outline">Find equipment ${icon('arrow')}</a></div>`;return `<div class="table-scroll"><table><thead><tr><th>Equipment</th>${state.user.role==='staff'?'<th>Learner</th>':''}<th>Dates</th><th>Status</th><th class="align-right">${compact?'':'Next step'}</th></tr></thead><tbody>${loans.map(l=>`<tr><td><div class="table-equipment"><span class="tiny-art">${icon(l.icon)}</span><div><strong>${esc(l.asset_name)}</strong><small>${esc(l.code)} · ${l.quantity} unit${l.quantity>1?'s':''}</small></div></div></td>${state.user.role==='staff'?`<td><strong>${esc(l.borrower)}</strong><small>${esc(l.student_id)}</small></td>`:''}<td>${date(l.starts_on)} – ${date(l.ends_on)}<small>${l.ends_on.slice(0,4)}</small></td><td>${badge(l)}</td><td class="align-right"><button class="text-button" data-loan="${l.id}">${compact?'View':l.status==='pending'&&state.user.role==='staff'?'Review':'Details'} ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function pageContent(){return {catalog,planner,loans,maintenance,insights,activity}[state.page]?.()||dashboard();}
function dashboard(){const recommended=[...state.assets].sort((a,b)=>a.uses-b.uses).filter(a=>a.available>0).slice(0,3);return `${hero()}${statCards()}${commonsPanels()}<div class="section-heading"><div><span class="eyebrow">LESS SITTING IDLE. MORE MAKING.</span><h2>A little inspiration for your next project</h2></div><a class="text-button" href="#catalog">View all equipment ${icon('arrow')}</a></div><section class="equipment-grid">${recommended.map(assetCard).join('')}</section><section class="recent-section"><div class="section-heading"><div><span class="eyebrow">YOUR WORKSPACE JOURNAL</span><h2>${state.user.role==='staff'?'At the borrowing desk':'Your borrowing, at a glance'}</h2></div><a class="text-button" href="#loans">View all ${icon('arrow')}</a></div>${loanRows(state.loans.filter(l=>!['rejected','cancelled'].includes(l.status)).slice(0,4),true)}</section><section class="reuse-strip">${icon('leaf')}<div><h3>A shared tool can start more than one story.</h3><p>Return it with care. Help the next learner make something good.</p></div><span>SDG 04 / 12</span></section>`;}
function catalog(){const categories=['All equipment',...new Set(state.assets.map(a=>a.category))],assets=state.assets.filter(a=>(state.category==='All equipment'||a.category===state.category)&&(!state.availability||a.available>0)&&(!state.query||[a.name,a.category,a.code,...a.tags].join(' ').toLowerCase().includes(state.query.toLowerCase())));return `<div class="page-intro"><span class="eyebrow">THE SHARED TOOLBOX</span><h1>Find a tool.<br><em>Start something.</em></h1><p>Good equipment is here to be used. Choose your dates and find what fits.</p></div><section class="catalog-toolbar"><label class="search-field">${icon('search')}<input type="search" id="equipment-search" placeholder="Search equipment, category or code" value="${esc(state.query)}" aria-label="Search equipment"></label><form id="date-filter" class="date-filter"><label>From<input type="date" name="from" value="${state.from}" min="${state.today}" required></label><span>–</span><label>Return by<input type="date" name="to" value="${state.to}" min="${dayAdd(state.from,1)}" required></label><button class="button primary small" type="submit">Check dates</button></form></section><div class="category-toolbar"><div class="category-tabs" role="group" aria-label="Equipment category">${categories.map(c=>`<button data-category-filter="${esc(c)}" class="category-tab ${state.category===c?'selected':''}">${esc(c)}</button>`).join('')}</div><label class="check-label"><input id="available-filter" type="checkbox" ${state.availability?'checked':''}>Available only</label></div>${state.user.role==='staff'?`<div class="inventory-action"><button class="button outline small" data-action="add-inventory">${icon('plus')}Add equipment</button></div>`:''}<div class="catalog-result-count"><span>${assets.length} types of equipment</span><span>Availability for ${date(state.from)} – ${date(state.to)}</span></div><section class="equipment-grid catalog-grid">${assets.map(assetCard).join('')||`<div class="empty-state"><h3>No equipment matches yet</h3><p>Try another keyword or category.</p><button class="button outline" data-action="clear-filters">Clear filters</button></div>`}</section><p class="data-note">${icon('info')} A request is confirmed after lab approval. Equipment in use stays unavailable until its return is recorded.</p>`;}
function loans(){const pending=state.loans.filter(l=>l.status==='pending').sort((a,b)=>a.prior_loans-b.prior_loans||a.created_at.localeCompare(b.created_at)||a.id-b.id);return `<div class="page-intro row-intro"><div><span class="eyebrow">THE BORROWING JOURNAL</span><h1>${state.user.role==='staff'?'Good decisions.':'Good things,'}<br><em>${state.user.role==='staff'?'Clear handovers.':'on loan.'}</em></h1><p>${state.user.role==='staff'?'Review requests, record pickups and make every return count.':'Track your requests and get ready for your next project.'}</p></div><a class="button outline" href="/api/export.csv">${icon('download')}Export CSV</a></div>${state.user.role==='staff'&&pending.length?`<section class="fair-access"><div class="fair-access-heading">${icon('user')}<div><h3>A fair chance to get started</h3><p>Fewer completed loans in the last 30 days come first. Request time breaks ties. The lab team makes the final decision.</p></div><span class="badge approved">${pending.length} to review</span></div><div class="priority-list">${pending.map(l=>`<button class="priority-item" data-loan="${l.id}"><span class="avatar">${esc(l.borrower[0])}</span><div><strong>${esc(l.borrower)}</strong><small>${esc(l.asset_name)} · ${esc(l.priority_reason)}</small></div><span>Review ${icon('arrow')}</span></button>`).join('')}</div></section>`:''}<section class="recent-section"><div class="section-heading"><h2>${state.user.role==='staff'?'All borrowing activity':'Your requests & loans'}</h2><label class="select-label">Show<select id="loan-status"><option value="all">All statuses</option>${Object.entries(statusLabel).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><div id="loan-table">${loanRows(state.loans)}</div></section>`;}
function maintenance(){const open=state.maintenance.filter(x=>x.status==='open'),closed=state.maintenance.filter(x=>x.status==='resolved');return `<div class="page-intro"><span class="eyebrow">CARE IS PART OF SHARING</span><h1>A longer life<br><em>for good tools.</em></h1><p>Equipment with a reported issue is held back until the lab team records its inspection.</p></div><div class="maintenance-summary"><strong>${state.stats.maintenance_units}</strong><span>units under care</span><strong>${state.stats.repairs_completed}</strong><span>completed inspections</span></div><section class="maintenance-grid">${open.map(m=>`<article class="repair-card"><div class="repair-card-top"><span class="tiny-art">${icon(m.icon)}</span><span class="badge pending">Inspection open</span></div><span class="equipment-code">${esc(m.code)}</span><h2>${esc(m.asset_name)}</h2><p>${esc(m.note)}</p><div class="repair-card-bottom"><span>${m.quantity} unit${m.quantity>1?'s':''} held · ${date(m.created_at)}</span><button class="button primary small" data-repair="${m.id}">Record inspection ${icon('check')}</button></div></article>`).join('')||`<div class="empty-state">${icon('check')}<h3>Everything is ready to share</h3><p>New inspection requests will appear here.</p></div>`}</section>${closed.length?`<section class="recent-section"><h2>Back in circulation</h2>${closed.map(m=>`<div class="repair-history">${icon('leaf')}<strong>${esc(m.asset_name)}</strong><p>${esc(m.resolution)}</p><span>${date(m.resolved_at)}</span></div>`).join('')}</section>`:''}`;}
function insights(){const s=state.stats;return `<div class="page-intro"><span class="eyebrow">SMALL ACTIONS, A CLEARER PICTURE</span><h1>See what's shared.<br><em>See what's possible.</em></h1><p>Understand access, borrowing and care using the records in this workspace.</p></div>${statCards()}<div class="insights-grid"><section class="insight-panel"><span class="eyebrow">THE TOOLBOX TODAY</span><h2>Ready to share, by category</h2><div class="category-bars">${s.by_category.map(c=>`<div class="category-bar"><div><strong>${esc(c.category)}</strong><span>${c.available} / ${c.total} units ready</span></div><svg viewBox="0 0 500 12" preserveAspectRatio="none" aria-label="${esc(c.category)}: ${c.available} of ${c.total} available"><rect width="500" height="12" rx="6" fill="#e7e8de"/><rect width="${c.available/c.total*500}" height="12" rx="6" fill="#2d6754"/></svg></div>`).join('')}</div></section><section class="access-panel"><span class="eyebrow">LEARNING WITH SHARED RESOURCES</span><strong>${s.learners}</strong><h2>learners with confirmed access</h2><p>Distinct learners with an approved, collected or completed loan in this workspace.</p><div><span>Returns on time</span><b>${s.on_time_rate===null?'—':s.on_time_rate+'%'}</b></div><small>${s.on_time} of ${s.completed} recorded returns</small></section></div><section class="recent-section"><div class="section-heading"><div><span class="eyebrow">USE WHAT IS ALREADY HERE</span><h2>Equipment with room for more ideas</h2></div><span class="muted">Fewest completed loans in the last 30 days</span></div><div class="underused-list">${[...state.assets].sort((a,b)=>a.uses-b.uses).slice(0,4).map(a=>`<button data-asset="${a.id}"><span class="tiny-art">${icon(a.icon)}</span><strong>${esc(a.name)}</strong><span>${a.uses} completed loans</span>${icon('arrow')}</button>`).join('')}</div></section><div class="method-note">${icon('info')}<p><strong>How to read these numbers</strong>Availability excludes maintenance holds and overlapping approved or collected loans. On-time returns use the recorded return date. ${state.demo?'These are illustrative workspace records. They are not results from a university pilot.':''} Environmental savings are not estimated here.</p></div>`;}
function activity(){return `<div class="page-intro"><span class="eyebrow">THE WORKSPACE RECORD</span><h1>Every action<br><em>leaves a trail.</em></h1><p>A timeline of requests, handovers and equipment care.</p></div><section class="journal" id="event-list"><p class="muted">Reading your journal…</p></section>`;}
function openModal(html){const m=$('#modal');m.innerHTML=`<button class="modal-close icon-button" aria-label="Close dialog">${icon('close')}</button>${html}`;m.showModal();m.scrollTop=0;m.querySelector('.modal-close').onclick=()=>m.close();}
async function assetModal(id){try{const {asset:a,history,alternatives}=await api('/assets/'+id+'?from='+state.from+'&to='+state.to);openModal(`<div class="asset-modal-head art-${a.id%4}">${productArt(a.icon)}<span>${esc(a.code)}</span></div><div class="modal-body"><span class="eyebrow">${esc(a.category)} · ${esc(a.location)}</span><h2 id="modal-title">${esc(a.name)}</h2><p>${esc(a.description)}</p><div class="asset-facts"><span><strong>${a.available}</strong>available for checked dates</span><span><strong>${a.total}</strong>shared units</span><span><strong>${a.maintenance}</strong>under care</span></div><div class="tags">${a.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div>${state.user.role==='student'?`<form id="reservation-form"><input type="hidden" name="asset_id" value="${a.id}"><div class="form-grid"><label>Borrow from<input type="date" name="starts_on" value="${state.from}" min="${state.today}" required></label><label>Return by<input type="date" name="ends_on" value="${state.to}" min="${dayAdd(state.from,1)}" required></label></div><div class="form-grid"><label>Quantity<input name="quantity" type="number" value="1" min="1" max="${Math.min(a.total,20)}" required></label><div class="form-hint">Borrow for up to 7 days.<br>Confirmed after lab approval.</div></div><label>Your learning purpose<textarea name="purpose" placeholder="Tell the lab team what you are working on…" maxlength="400" required></textarea></label><p id="reservation-error" class="form-error" role="alert"></p><button class="button primary wide" type="submit">Request equipment ${icon('arrow')}</button></form>`:'<p class="notice">Learners request equipment from their own workspace. Review their requests at the borrowing desk.</p>'}${alternatives.length?`<div class="alternatives"><h3>Other tools in this category</h3>${alternatives.map(x=>`<button class="text-button" data-alternative="${x.id}">${esc(x.name)} <span>${x.available} ready ${icon('arrow')}</span></button>`).join('')}</div>`:''}<details class="asset-history"><summary>Equipment care history</summary>${history.length?history.map(h=>`<div><small>${date(h.created_at)}</small><p>${esc(h.detail)}</p></div>`).join(''):'<p>No condition changes have been recorded yet.</p>'}</details></div>`);
 $('#reservation-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const f=Object.fromEntries(new FormData(e.target));f.quantity=Number(f.quantity);f.asset_id=Number(f.asset_id);const data=await api('/loans',{method:'POST',body:f});$('#modal').close();state.page='loans';location.hash='loans';await load();toast(data.message);}catch(error){$('#reservation-error').textContent=error.message;button.disabled=false;}});document.querySelectorAll('[data-alternative]').forEach(b=>b.onclick=()=>{$('#modal').close();assetModal(Number(b.dataset.alternative));});
 }catch(e){toast(e.message,true);}}
function loanModal(id){const l=state.loans.find(x=>x.id===id);if(!l)return;const staff=state.user.role==='staff';let actions='';
 if(staff&&l.status==='pending')actions=`<div class="priority-explanation">${icon('user')}<p>${esc(l.priority_reason)}. The final approval also depends on availability for these dates.</p></div><label>Decision notes<textarea id="decision-note" placeholder="Add context for the learner" maxlength="400"></textarea></label><div class="modal-actions"><button class="button outline" data-transition="reject">Decline request</button><button class="button primary" data-transition="approve">Approve request ${icon('check')}</button></div>`;
 if(staff&&l.status==='approved')actions=`<p class="notice">Confirm that the learner has received the equipment before recording pickup.</p><button class="button primary wide" data-transition="checkout">Record pickup ${icon('check')}</button>`;
 if(staff&&l.status==='checked_out')actions=`<form id="return-form"><label>Condition at return<select name="condition"><option value="good">Good · ready to share</option><option value="repair">Needs repair or inspection</option><option value="retire">Unsafe · hold for assessment</option></select></label><label>Inspection notes<textarea name="notes" maxlength="500" placeholder="Record any issue or inspection details"></textarea></label><p class="notice">Equipment with an issue will be held for inspection before it can be borrowed again.</p><button class="button primary wide" type="submit">Record return ${icon('check')}</button></form>`;
 if(!staff&&['pending','approved'].includes(l.status))actions=`<p class="notice">${l.status==='pending'?'The lab team is reviewing your request. Approval will appear here.':'Visit the lab during your approved dates to collect your equipment.'}</p><button class="button outline wide" data-transition="cancel">Cancel this request</button>`;
 openModal(`<div class="modal-body"><span class="eyebrow">BORROWING RECORD PL-${String(l.id).padStart(4,'0')}</span><h2 id="modal-title">${esc(l.asset_name)}</h2>${badge(l)}${loanJourney(l)}<div class="loan-facts"><div><span>Learner</span><strong>${esc(l.borrower)}</strong></div><div><span>Quantity</span><strong>${l.quantity} unit${l.quantity>1?'s':''}</strong></div><div><span>Borrow from</span><strong>${date(l.starts_on)}</strong></div><div><span>Return by</span><strong>${date(l.ends_on)}</strong></div></div><h3>Learning purpose</h3><p>${esc(l.purpose)}</p>${l.decision_note?`<h3>Lab notes</h3><p>${esc(l.decision_note)}</p>`:''}${l.return_condition?`<h3>Return inspection</h3><p>${esc(l.return_condition==='good'?'Ready to share':l.return_condition==='repair'?'Held for repair':'Held for assessment')}. ${esc(l.return_notes)}</p>`:''}${actions}<p class="form-error" id="loan-error" role="alert"></p></div>`);
 document.querySelectorAll('[data-transition]').forEach(b=>b.onclick=()=>transition(l.id,b.dataset.transition,{note:$('#decision-note')?.value||''},b));$('#return-form')?.addEventListener('submit',e=>{e.preventDefault();transition(l.id,'return',Object.fromEntries(new FormData(e.target)),e.target.querySelector('button'));});}
async function transition(id,action,body,button){button.disabled=true;try{const d=await api(`/loans/${id}/${action}`,{method:'POST',body});$('#modal').close();await load();toast(d.message);}catch(e){$('#loan-error').textContent=e.message;button.disabled=false;}}
function repairModal(id){const m=state.maintenance.find(x=>x.id===id);openModal(`<div class="modal-body"><span class="eyebrow">EQUIPMENT CARE</span><h2 id="modal-title">${esc(m.asset_name)}</h2><p>${esc(m.note)}</p><form id="repair-form"><label>Inspection or repair completed<textarea name="note" placeholder="Describe the checks or repair completed before release" required maxlength="500"></textarea></label><p class="notice">Recording this inspection releases ${m.quantity} unit${m.quantity>1?'s':''} back to the equipment library.</p><p id="repair-error" class="form-error" role="alert"></p><button class="button primary wide" type="submit">Complete inspection ${icon('check')}</button></form></div>`);$('#repair-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=await api(`/maintenance/${id}/resolve`,{method:'POST',body:Object.fromEntries(new FormData(e.target))});$('#modal').close();await load();toast(d.message);}catch(error){$('#repair-error').textContent=error.message;b.disabled=false;}};}
function registerModal(){openModal(`<div class="modal-body"><span class="eyebrow">JOIN THE COMMONS</span><h2 id="modal-title">Make room for your ideas.</h2><form id="register-form"><label>Full name<input name="name" required maxlength="100" autocomplete="name"></label><label>Student ID<input name="student_id" required maxlength="40"></label><label>Email<input name="email" type="email" required maxlength="160" autocomplete="username"></label><label>Password<input name="password" type="password" minlength="10" required autocomplete="new-password"><small>At least 10 characters.</small></label><p class="form-error" id="register-error" role="alert"></p><button class="button primary wide" type="submit">Create learner account ${icon('arrow')}</button></form></div>`);$('#register-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{Object.assign(state,await api('/auth/register',{method:'POST',body:Object.fromEntries(new FormData(e.target))}));$('#modal').close();await load();toast('Welcome to the commons.');}catch(error){$('#register-error').textContent=error.message;b.disabled=false;}};}
function inventoryModal(){openModal(`<div class="modal-body"><span class="eyebrow">GROW THE SHARED TOOLBOX</span><h2 id="modal-title">Add equipment to the commons.</h2><form id="inventory-form"><div class="form-grid"><label>Equipment code<input name="code" required maxlength="30" placeholder="ELE-040"></label><label>Number of units<input name="total" type="number" min="1" max="200" value="1" required></label></div><label>Equipment name<input name="name" required maxlength="100"></label><div class="form-grid"><label>Category<input name="category" list="equipment-categories" required maxlength="60"><datalist id="equipment-categories">${[...new Set(state.assets.map(a=>a.category))].map(c=>`<option value="${esc(c)}">`).join('')}</datalist></label><label>Storage location<input name="location" required maxlength="80"></label></div><label>Description<textarea name="description" required maxlength="400" placeholder="Describe what learners can do with this equipment."></textarea></label><label>Equipment symbol<select name="icon">${[['chip','Electronics kit'],['camera','Camera'],['scope','Microscope'],['meter','Multimeter'],['audio','Audio recorder'],['printer','Fabrication station'],['laptop','Laptop'],['tripod','Lighting kit'],['sensor','Sensor kit'],['projector','Projector'],['ruler','Measurement kit'],['vr','VR headset']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><p class="form-error" id="inventory-error" role="alert"></p><button class="button primary wide" type="submit">Add to the library ${icon('plus')}</button></form></div>`);$('#inventory-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.total=Number(data.total);const r=await api('/assets',{method:'POST',body:data});$('#modal').close();await load();toast(r.message);}catch(error){$('#inventory-error').textContent=error.message;b.disabled=false;}};}
function notifications(){const p=$('#notifications');p.hidden=!p.hidden;if(!p.hidden){p.innerHTML=`<div class="notification-header"><h2>Your updates</h2><button class="icon-button" aria-label="Close notifications">${icon('close')}</button></div>${state.notifications.length?state.notifications.map(n=>`<article class="notification ${n.read_at?'':'unread'}"><span class="live-dot"></span><div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${date(n.created_at)}</small></div></article>`).join(''):'<p class="muted">You are all caught up.</p>'}`;p.querySelector('button').onclick=()=>p.hidden=true;api('/notifications/read',{method:'POST',body:{}}).then(()=>state.notifications.forEach(n=>n.read_at ||= new Date().toISOString())).catch(e=>toast(e.message,true));}}
function bind(){document.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>assetModal(Number(b.dataset.asset)));document.querySelectorAll('[data-loan]').forEach(b=>b.onclick=()=>loanModal(Number(b.dataset.loan)));document.querySelectorAll('[data-repair]').forEach(b=>b.onclick=()=>repairModal(Number(b.dataset.repair)));
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action;if(a==='account'){openModal(`<div class="modal-body"><span class="eyebrow">YOUR WORKSPACE</span><h2 id="modal-title">${esc(state.user.name)}</h2><p>${esc(state.user.email)}</p><button id="sign-out" class="button primary wide">Sign out ${icon('logout')}</button></div>`);$('#sign-out').onclick=async()=>{try{await api('/auth/logout',{method:'POST',body:{}});$('#modal').close();state.user=null;Object.assign(state,await api('/session'));render();}catch(e){toast(e.message,true);}};}if(a==='quick-find')quickFind();if(a==='motion')toggleMotion();if(a==='planner-refresh')fetchPlanner();if(a==='add-inventory')inventoryModal();if(a==='notifications')notifications();if(a==='menu'){const open=$('.sidebar').classList.toggle('mobile-open');const trigger=$('.mobile-menu');trigger?.setAttribute('aria-expanded',String(open));trigger?.setAttribute('aria-label',open?'Close navigation':'Open navigation');}if(a==='clear-filters'){state.query='';state.category='All equipment';state.availability=false;render();}});
 document.querySelectorAll('[data-category-filter]').forEach(b=>b.onclick=()=>{state.category=b.dataset.categoryFilter;render();});$('#equipment-search')?.addEventListener('input',e=>{const position=e.target.selectionStart;state.query=e.target.value;render();const input=$('#equipment-search');input.focus();try{input.setSelectionRange(position,position);}catch{}});$('#available-filter')?.addEventListener('change',e=>{state.availability=e.target.checked;render();});$('#date-filter')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{const r=await api(`/assets?from=${d.from}&to=${d.to}`);state.assets=r.assets;state.from=d.from;state.to=d.to;render();toast('Availability updated for your dates.');}catch(error){toast(error.message,true);}});
 $('#loan-status')?.addEventListener('change',e=>{const rows=e.target.value==='all'?state.loans:state.loans.filter(l=>l.status===e.target.value);$('#loan-table').innerHTML=loanRows(rows);$('#loan-table').querySelectorAll('[data-loan]').forEach(b=>b.onclick=()=>loanModal(Number(b.dataset.loan)));});
 bindExperience();if(state.page==='activity')api('/events').then(r=>{if($('#event-list'))$('#event-list').innerHTML=r.events.map(e=>`<article class="journal-item"><span class="journal-dot"></span><div><strong>${esc(e.action.replaceAll('_',' '))}</strong><p>${esc(e.detail)}</p><small>${esc(e.actor||'Workspace')} · ${date(e.created_at)}</small></div></article>`).join('');}).catch(e=>toast(e.message,true));}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next==='main')return;state.page=['dashboard','catalog','planner','loans','maintenance','insights','activity'].includes(next)?next:'dashboard';if(state.user?.role==='student'&&['maintenance','activity'].includes(state.page))state.page='dashboard';$('#notifications').hidden=true;render();window.scrollTo({top:0,behavior:'instant'});});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#notifications').hidden=true;$('.sidebar')?.classList.remove('mobile-open');$('.mobile-menu')?.setAttribute('aria-expanded','false');$('.mobile-menu')?.setAttribute('aria-label','Open navigation');}});

const productArt=name=>`<svg class="equipment-object" viewBox="0 0 320 210" aria-hidden="true"><use href="/assets/equipment-collection.svg#${Object.hasOwn(icons,name)?name:'chip'}"></use></svg>`;
let motionPage='',motionObserver,plannerRequest=0;
const motionMedia=window.matchMedia('(prefers-reduced-motion: reduce)');
function motionReduced(){try{return motionMedia.matches||localStorage.getItem('pinjamlab-motion')==='reduced';}catch{return motionMedia.matches;}}
function toggleMotion(){try{localStorage.setItem('pinjamlab-motion',motionReduced()?'full':'reduced');}catch{}setupMotion();toast(motionReduced()?'Reduced motion is enabled.':'Interface motion is enabled.');}
function setupMotion(){const reduced=motionReduced();document.documentElement.classList.toggle('reduce-motion',reduced);const toggle=$('[data-action="motion"]');if(toggle){toggle.setAttribute('aria-pressed',String(reduced));toggle.setAttribute('aria-label',reduced?'Interface motion reduced':'Reduce interface motion');toggle.querySelector('span').textContent=reduced?'Still':'Motion';}if(reduced){motionObserver?.disconnect();document.querySelectorAll('.reveal-item').forEach(e=>e.classList.add('revealed'));document.querySelectorAll('[data-count]').forEach(e=>e.textContent=e.dataset.count);return;}const key=state.user?state.page:'login';if(motionPage===key)return;motionPage=key;const main=$('#main');main?.classList.add('page-enter');setTimeout(()=>main?.classList.remove('page-enter'),900);motionObserver?.disconnect();motionObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;entry.target.classList.add('revealed');motionObserver.unobserve(entry.target);if(entry.target.matches('[data-count]')){const value=Number(entry.target.dataset.count),start=performance.now();const tick=now=>{if(!entry.target.isConnected)return;const progress=Math.min((now-start)/850,1);entry.target.textContent=String(Math.round(value*(1-Math.pow(1-progress,3))));if(progress<1&&!motionReduced())requestAnimationFrame(tick);else entry.target.textContent=String(value);};requestAnimationFrame(tick);}}},{threshold:.12});document.querySelectorAll('.equipment-card,.commons-panel,.insight-panel,.repair-card,.journey-flow,[data-count]').forEach((el,i)=>{el.classList.add('reveal-item','reveal-delay-'+i%4);motionObserver.observe(el);});}
motionMedia.addEventListener('change',setupMotion);
function commonsPanels(){const s=state.stats,total=s.total_units||0,ready=s.available_units||0,percent=total?Math.round(ready/total*100):0;const task=state.loans.filter(l=>['approved','checked_out','pending'].includes(l.status)).sort((a,b)=>a.ends_on.localeCompare(b.ends_on))[0];return `<section class="commons-grid"><article class="commons-panel readiness-panel"><div><span class="eyebrow">A WELL-USED COMMONS</span><h2>Good tools.<br>Ready for good ideas.</h2><p>${ready} of ${total} units available today. Care and confirmed loans are included in the check.</p><a href="#insights" class="text-button">Read the workspace ${icon('arrow')}</a></div><div class="readiness-dial"><svg viewBox="0 0 120 120" role="img" aria-label="${percent} percent of units available today"><circle cx="60" cy="60" r="49" fill="none" stroke="#dee5d3" stroke-width="9"/><circle class="dial-arc" cx="60" cy="60" r="49" fill="none" stroke="#184d3e" stroke-width="9" stroke-linecap="round" stroke-dasharray="${percent*3.0788} 307.88" transform="rotate(-90 60 60)"/></svg><strong>${percent}<small>%</small></strong><span>ready today</span></div></article><article class="commons-panel next-panel"><span class="eyebrow"><i></i> ${state.user.role==='staff'?'AT THE BORROWING DESK':'YOUR NEXT CHAPTER'}</span>${task?`<div class="next-tool">${productArt(task.icon)}<div><span>${esc(task.code)}</span><h2>${esc(task.asset_name)}</h2>${badge(task)}</div></div><a class="next-action" href="#loans"><span>${task.status==='checked_out'?'Return by '+date(task.ends_on):task.status==='approved'?'Pickup from '+date(task.starts_on):'A request is ready for review'}</span>${icon('arrow')}</a>`:`<h2>There is room for<br>your next idea.</h2><p>Look ahead, find your dates, and make the most of what is already here.</p><a class="next-action" href="#planner"><span>Open the weekly planner</span>${icon('arrow')}</a>`}</article></section><section class="journey-flow" aria-label="Equipment sharing cycle"><div><span class="eyebrow">MADE TO GO AROUND</span><h2>One tool. Many chapters.</h2></div><a href="#catalog"><b>01</b><span>Discover</span>${icon('search')}</a><span class="flow-link" aria-hidden="true"></span><a href="#planner"><b>02</b><span>Plan & borrow</span>${icon('calendar')}</a><span class="flow-link" aria-hidden="true"></span><a href="#loans"><b>03</b><span>Create & return</span>${icon('check')}</a><span class="flow-link" aria-hidden="true"></span><a href="#${state.user.role==='staff'?'maintenance':'insights'}"><b>04</b><span>Care & repeat</span>${icon('leaf')}</a></section>`;}
function loanJourney(l){const names=['Requested','Approved','Collected','Returned'],current={pending:0,approved:1,checked_out:2,returned:3}[l.status];if(current===undefined)return `<div class="journey-closed">${icon('info')}This request was ${l.status==='rejected'?'declined':'cancelled'}. No further handover is scheduled.</div>`;return `<ol class="loan-journey" aria-label="Loan progress">${names.map((name,i)=>`<li class="${i<current?'complete':i===current?'current':''}"><span>${i<current?icon('check'):String(i+1).padStart(2,'0')}</span><strong>${name}</strong></li>`).join('')}</ol>${l.status==='returned'&&l.return_condition!=='good'?`<p class="journey-care-note">${icon('tool')}The loan is closed. Equipment readiness is managed separately through its care record.</p>`:''}`;}
function planner(){state.weekStart ||= state.today;return `<div class="page-intro row-intro planner-intro"><div><span class="eyebrow">A LITTLE PLANNING. MORE POSSIBILITIES.</span><h1>Find your window.<br><em>Make it happen.</em></h1><p>Seven days of availability, checked against the shared inventory.</p></div><span class="planner-edition">THE WEEK AHEAD<br><b>07</b></span></div><section class="planner-controls"><form id="planner-date"><label>Window starts<input type="date" name="from" min="${state.today}" max="${dayAdd(state.today,84)}" value="${state.weekStart}" required></label><button class="button primary" type="submit">Check this week ${icon('arrow')}</button></form><div class="week-step"><button class="icon-button" data-week="-1" aria-label="Previous seven days" ${state.weekStart<=state.today?'disabled':''}>${icon('chevron','previous')}</button><span>${date(state.weekStart)} – ${date(dayAdd(state.weekStart,6))}</span><button class="icon-button" data-week="1" aria-label="Next seven days" ${dayAdd(state.weekStart,7)>dayAdd(state.today,84)?'disabled':''}>${icon('chevron')}</button></div><button class="text-button" data-action="planner-refresh">Refresh ${icon('arrow')}</button></section><div class="planner-key"><div><span class="legend-dot ready"></span>Units available <span class="legend-dot none"></span>None available</div><label>Category<select id="planner-category"><option>All categories</option>${[...new Set(state.assets.map(a=>a.category))].map(c=>`<option ${state.plannerCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div><section id="planner-board" class="planner-board"><div class="planner-loading"><span></span><span></span><span></span><p>Checking the shared toolbox…</p></div></section><div class="planner-explainer"><div>${icon('calendar')}<h3>Choose a day to begin</h3><p>Each cell shows units available for that day. Choose an available cell to open the equipment and start a request.</p></div><div>${icon('tool')}<h3>Care stays in the calculation</h3><p>Inspection holds and confirmed or collected loans reduce availability. Pending requests do not reserve a unit.</p></div><div>${icon('check')}<h3>Confirm at the right moment</h3><p>Multi-day requests are checked for their full date range. The lab rechecks capacity at final approval.</p></div></div>`;}
function drawPlanner(){const d=state.plannerData;if(!d||!$('#planner-board'))return;const assets=d.assets.filter(a=>state.plannerCategory==='All categories'||a.category===state.plannerCategory);$('#planner-board').innerHTML=`<div class="planner-scroll"><table class="availability-table"><caption>Available units by day. Return dates are exclusive.</caption><thead><tr><th scope="col">The shared collection<span>${assets.length} equipment types</span></th>${d.days.map(day=>`<th scope="col" class="${day===state.today?'is-today':''}"><small>${new Intl.DateTimeFormat('en-GB',{weekday:'short',timeZone:'UTC'}).format(new Date(day+'T12:00:00Z'))}</small><strong>${day.slice(8)}</strong>${day===state.today?'<span>Today</span>':''}</th>`).join('')}</tr></thead><tbody>${assets.map(a=>`<tr><th scope="row"><div>${productArt(a.icon)}<span><strong>${esc(a.name)}</strong><small>${esc(a.code)} · ${a.total} shared units</small></span></div></th>${d.days.map((day,i)=>`<td><button class="availability-cell ${a.available[i]?'ready':'unavailable'}" data-plan-asset="${a.id}" data-plan-day="${day}" ${a.available[i]?'':'disabled'} aria-label="${esc(a.name)}: ${a.available[i]} unit${a.available[i]===1?'':'s'} available on ${date(day)}"><strong>${a.available[i]}</strong><span>${a.available[i]?'available':'unavailable'}</span>${a.available[i]?icon('arrow'):''}</button></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="planner-bottom" role="status"><span>${icon('check')}Checked against current workspace records</span><span>${date(d.from)} – ${date(dayAdd(d.to,-1))}</span></div>`;$('#planner-board').querySelectorAll('[data-plan-asset]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await api(`/assets?from=${b.dataset.planDay}&to=${dayAdd(b.dataset.planDay,1)}`);state.from=r.from;state.to=r.to;state.assets=r.assets;await assetModal(Number(b.dataset.planAsset));}catch(e){toast(e.message,true);}finally{if(b.isConnected)b.disabled=false;}});}
async function fetchPlanner(){const request=++plannerRequest,from=state.weekStart||state.today;const refresh=$('[data-action="planner-refresh"]');if(refresh)refresh.disabled=true;try{const data=await api('/availability?from='+encodeURIComponent(from));if(request!==plannerRequest||state.page!=='planner'||state.weekStart!==from)return;state.plannerData=data;drawPlanner();}catch(e){if(request===plannerRequest&&$('#planner-board'))$('#planner-board').innerHTML=`<div class="empty-state"><h3>We could not check this week</h3><p>${esc(e.message)}</p><button class="button outline" id="planner-retry">Try again</button></div>`;$('#planner-retry')?.addEventListener('click',fetchPlanner);}finally{if(refresh?.isConnected)refresh.disabled=false;}}
function bindExperience(){if(state.page==='planner'){fetchPlanner();$('#planner-date')?.addEventListener('submit',e=>{e.preventDefault();state.weekStart=e.target.elements.from.value;render();});$('#planner-category')?.addEventListener('change',e=>{state.plannerCategory=e.target.value;drawPlanner();});document.querySelectorAll('[data-week]').forEach(b=>b.onclick=()=>{const candidate=dayAdd(state.weekStart,Number(b.dataset.week)*7);state.weekStart=candidate<state.today?state.today:candidate;render();});}}
function quickFind(){openModal(`<div class="modal-body command-body"><span class="eyebrow">THE COMMONS, AT YOUR FINGERTIPS</span><h2 id="modal-title">Find your next tool.</h2><label class="command-search">${icon('search')}<input id="command-search" type="search" aria-label="Find equipment in the workspace" placeholder="A tool, category or equipment code…" autocomplete="off"></label><div class="command-links"><a href="#planner">${icon('calendar')} Weekly planner</a><a href="#loans">${icon('box')} Borrowing journal</a></div><div id="command-results"></div><p class="command-help">Type to search · Tab to move · Enter to open · Esc to close</p></div>`);const input=$('#command-search');const draw=()=>{const query=input.value.toLowerCase().trim(),items=state.assets.filter(a=>!query||[a.name,a.code,a.category,...a.tags].join(' ').toLowerCase().includes(query)).slice(0,6);$('#command-results').innerHTML=items.length?items.map(a=>`<button class="command-result" data-command-asset="${a.id}"><span class="tiny-art">${icon(a.icon)}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.category)} · ${esc(a.code)}</small></span>${icon('arrow')}</button>`).join(''):'<div class="command-empty">No tools match yet. Try a category or another word.</div>';document.querySelectorAll('[data-command-asset]').forEach(b=>b.onclick=()=>{$('#modal').close();assetModal(Number(b.dataset.commandAsset));});};input.oninput=draw;input.onkeydown=e=>{if(e.key==='Enter'){$('[data-command-asset]')?.click();e.preventDefault();}if(e.key==='ArrowDown'){$('[data-command-asset]')?.focus();e.preventDefault();}};document.querySelectorAll('.command-links a').forEach(a=>a.onclick=()=>$('#modal').close());draw();input.focus();}
document.addEventListener('keydown',e=>{if(!state.user||$('#modal').open||e.target.closest('input,textarea,select,[contenteditable]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'||e.key==='/'){e.preventDefault();quickFind();}});

try{Object.assign(state,await api('/session'));state.from=state.today;state.to=dayAdd(state.today,1);state.page=location.hash.slice(1)||'dashboard';if(state.user)await load();else render();}catch(e){$('#app').innerHTML=`<main class="initial"><h1>Let's reconnect.</h1><p>${esc(e.message)}</p><button class="button primary" id="retry">Try again</button></main>`;$('#retry').onclick=()=>location.reload();}
